using System;
class Program{static int n;static void C(bool v,string s){if(!v)throw new Exception(s);n++;}
class Setup{public World W=new World();public EntityPlayer P;public ClientInfo S;public BlockPlantGrowingRebirth Crop=new BlockPlantGrowingRebirth();public SeedPlacementSessionAuthority.Reservation R;public SeedPlacementIntentCodecReview.Intent Intent;public SeedPlacementOriginalCommandReview Command;public Setup(){P=new EntityPlayer{entityId=1,world=W};W.Actors[1]=P;S=new ClientInfo{ClientNumber=1,entityId=1,PlatformId=new PlatformIdentity{Value="platform"},CrossplatformId=new PlatformIdentity{Value="cross"}};SingletonMonoBehaviour<ConnectionManager>.Instance=new ConnectionManager();SingletonMonoBehaviour<ConnectionManager>.Instance.Clients.Entries[1]=S;GameManager.Instance=new GameManager{World=W};GameManager.Instance.Players.Records[1]=new PersistentPlayerData{PrimaryId=new PlatformIdentity{Value="platform"}};BlockLimitTracker.instance=new BlockLimitTracker();SeedPlacementSessionAuthority.TryIssue(S,W,out var epoch);SeedPlacementSessionAuthority.TryReserve(S,W,epoch,1,out R);Intent=new SeedPlacementIntentCodecReview.Intent{OriginalCount=1,Slot=0,Target=new BlockValue{rawData=2,Block=Crop},Seed=new byte[]{1},Flags=0x15};Command=SeedPlacementOriginalCommandReview.Capture(epoch,1,1,1,Intent);}public void End()=>SeedPlacementSessionAuthority.Revoke(S);}
static void Main(){foreach(bool cross in new[]{false,true}){var s=new Setup();if(cross)GameManager.Instance.Players.Records[1].PrimaryId=s.S.CrossplatformId;C(ServerSeedPlacementPolicyReview.Check(s.R,s.Command,s.S,s.W,s.P)==ServerSeedPlacementPolicyReview.Stage.MissingServerEyeRay,"native permissions pass still missing eye/range "+cross);var policy=ServerSeedPlacementPolicyReview.CreateForReview();C(!policy.Validate(s.S,s.W,GameManager.Instance,s.R,s.Intent,new NetPackageSetBlock())&&policy.LastStage==ServerSeedPlacementPolicyReview.Stage.MissingServerEyeRay,"root policy interface never activates from partial proof");s.End();}
foreach(var fault in new[]{"derived","mature","crop","limit","persistent","identity","worldpermission","editor","sender","revoke","cropcallback","limitcallback","worldcallback"}){var s=new Setup();switch(fault){case "derived":s.Intent.Target=new BlockValue{rawData=2,Block=new DerivedCrop()};s.Command=SeedPlacementOriginalCommandReview.Capture(s.R.Epoch,1,1,1,s.Intent);break;case "mature":s.Crop.Seed=false;break;case "crop":s.Crop.Allowed=false;break;case "limit":BlockLimitTracker.instance.Allowed=false;break;case "persistent":GameManager.Instance.Players.Records.Clear();break;case "identity":GameManager.Instance.Players.Records[1].PrimaryId=new PlatformIdentity{Value="foreign"};break;case "worldpermission":s.W.Allowed=false;break;case "editor":GameManager.Instance.Editor=true;break;case "sender":s.S=new ClientInfo{ClientNumber=1,entityId=1,PlatformId=new PlatformIdentity{Value="platform"}};break;case "revoke":SeedPlacementSessionAuthority.Revoke(s.S);break;case "cropcallback":s.Crop.OnPermission=()=>SeedPlacementSessionAuthority.Revoke(s.S);break;case "limitcallback":BlockLimitTracker.instance.OnPermission=()=>GameManager.Instance.World=new World();break;case "worldcallback":s.W.OnPermission=()=>GameManager.Instance.Editor=true;break;}C(ServerSeedPlacementPolicyReview.Check(s.R,s.Command,s.S,s.W,s.P)==ServerSeedPlacementPolicyReview.Stage.Refused,"native permission refusal "+fault);s.End();}Console.WriteLine("PASS "+n+" linked partial host policy checks; native identity/protection adapters, no server eye-ray/placement permission granted.");}}
